SELECT CASE WHEN unit_price >= 360 THEN 'high' WHEN unit_price >= 180 THEN 'mid' ELSE 'low' END AS unit_price_bucket, MAX(unit_price) AS max_unit_price, ROUND(AVG(unit_price), 2) AS avg_unit_price FROM order_items WHERE quantity IS NOT NULL AND unit_price >= 220 GROUP BY CASE WHEN unit_price >= 360 THEN 'high' WHEN unit_price >= 180 THEN 'mid' ELSE 'low' END HAVING max_unit_price > 310 ORDER BY unit_price_bucket DESC;
